/**
 * @summary Update health note
 */
export const getUpdateHealthNoteUrl = (id: number) => {
  return `/api/health/notes/${id}`;
};

export const updateHealthNote = async (
  id: number,
  updateHealthNoteInput: UpdateHealthNoteInput,
  options?: RequestInit,
): Promise<HealthNote> => {
  return customFetch<HealthNote>(getUpdateHealthNoteUrl(id), {
    ...options,
    method: "PATCH",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(updateHealthNoteInput),
  });
};

export const getUpdateHealthNoteMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof updateHealthNote>>,
    TError,
    { id: number; data: BodyType<UpdateHealthNoteInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof updateHealthNote>>,
  TError,
  { id: number; data: BodyType<UpdateHealthNoteInput> },
  TContext
> => {
  const mutationKey = ["updateHealthNote"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof updateHealthNote>>,
    { id: number; data: BodyType<UpdateHealthNoteInput> }
  > = (props) => {
    const { id, data } = props ?? {};

    return updateHealthNote(id, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

